using System;
namespace DeliveryService.Mok.Stocks {
[Serializable] public sealed class StockEvent {
    public int company;public string title,alternate,body,goodTitle,goodBody,badTitle,badBody;
    public StockEvent(int c,string t,string a,string b,string gt,string gb,string bt,string bb){company=c;title=t;alternate=a;body=b;goodTitle=gt;goodBody=gb;badTitle=bt;badBody=bb;}
}
public static class StockCatalog {
    public static readonly string[] Names={"모터웍스","시티에너지","퀵박스","치즈팜","네온테크"};
    public static readonly string[] Sectors={"오토바이·부품","주유·연료","배달·물류","피자 식재료","전자기기"};
    public static readonly int[] StartingPrices={800,600,450,350,1100};
    public static readonly float[] Volatility={.004f,.0025f,.004f,.002f,.007f};
    // 첫 보도와 두 가지 후속 결과가 같은 사건을 설명한다.
    public static readonly StockEvent[] Events={
        new StockEvent(0,"신형 바이크 예약 매진","새 바이크 주문 몰려…출고 일정 주목","신형 바이크의 초기 예약 물량이 소진됐다. 추가 생산을 검토 중이지만 핵심 부품 공급 일정은 확정되지 않았다.","추가 부품 확보…예약 차량 출고 시작","대체 공급 계약이 체결되며 출고가 시작됐다. 회사는 남은 예약 물량도 순차적으로 납품할 계획이다.","출고 연기에 예약 취소 증가","부품 입고 지연으로 출고가 연기됐다. 예약 취소가 늘면서 예상 매출 달성에 차질이 생겼다."),
        new StockEvent(0,"물류업체와 대량 공급 협상","배달 바이크 대형 계약 추진","물류업체가 업무용 바이크 대량 도입을 검토하고 있다. 협상 규모는 크지만 할인 폭과 유지보수 조건은 공개되지 않았다.","공급 계약 확정…정비 매출도 확보","장기 공급 계약에 정비 서비스가 포함됐다. 안정적인 추가 수익이 기대된다.","과도한 할인 요구에 계약 축소","가격 협상이 길어지며 계약 물량이 축소됐다. 예상했던 판매 확대 효과는 제한적이다."),
        new StockEvent(0,"핵심 부품 공급 차질","부품 입고 지연에 생산 일정 조정","주요 부품 업체의 납품이 늦어지고 있다. 회사는 대체 부품의 품질 검증을 진행 중이라고 밝혔다.","대체 부품 검증 통과","새 공급처의 부품이 검증을 통과했다. 생산은 정상 수준으로 돌아갈 전망이다.","생산 중단 장기화","대체 부품 검증에서 문제가 발견됐다. 생산 중단이 길어지며 납품 지연 비용이 늘고 있다."),
        new StockEvent(0,"일부 바이크 제동 문제 조사","신형 차량 품질 점검 착수","일부 고객이 제동 이상을 신고했다. 회사는 특정 생산분에 국한된 문제인지 조사하고 있다.","결함 범위 제한…수리 완료","문제는 소량의 생산분에서 확인됐다. 부품 교체가 마무리돼 추가 비용은 제한적일 전망이다.","리콜 대상 확대","추가 검사에서 결함 차량이 더 발견됐다. 리콜 비용 증가와 판매 위축이 우려된다."),
        new StockEvent(0,"생산시설 증설 계획 발표","공장 확대…수요 증가에 대응","회사가 조립 시설 확대를 추진한다. 생산 능력은 늘어나지만 공사비와 가동 일정이 변수다.","증설 공장 조기 가동","설비 설치가 계획보다 빨리 끝났다. 생산량이 증가하며 밀린 주문을 처리하기 시작했다.","공사 지연에 투자비 증가","설비 공사가 지연돼 추가 비용이 발생했다. 새 공장의 매출 기여 시점도 늦어졌다."),
        new StockEvent(1,"연료 운송 차질…주유 가격 상승","연료 재고 확보 여부에 관심","운송 노선 정비로 연료 공급이 줄었다. 회사는 재고를 확보했지만 다음 물량의 매입 가격은 오를 수 있다.","운송 재개…판매 공백 없이 공급 정상화","기존 재고가 소진되기 전에 공급이 재개됐다. 회사는 일시적인 판매 가격 상승의 수혜를 입었다.","공급 지연 장기화…판매 제한","재고가 줄면서 일부 지점이 판매를 제한했다. 비싼 대체 물량 확보도 부담이 되고 있다."),
        new StockEvent(1,"장기 연료 공급 계약 검토","연료 원가 안정화 협상 진행","회사가 고정 가격의 공급 계약을 검토한다. 공급 안정성이 장점이지만 향후 연료 시세에 따라 효과가 달라질 수 있다.","안정적인 매입 가격 확보","계약 체결 후 도매 가격이 올라 고정 가격의 이점이 커졌다. 공급 물량도 안정적으로 유지된다.","시세 하락에 계약 부담","계약 이후 도매 가격이 내려갔다. 회사는 당분간 시장보다 높은 가격으로 연료를 매입해야 한다."),
        new StockEvent(1,"신규 주유소 개장 준비","새 지점으로 도심 판매망 확대","유동 차량이 많은 지역에 새 주유소가 문을 연다. 주변 경쟁점들도 할인 행사를 예고했다.","신규 지점 이용객 증가","접근성이 좋은 새 지점에 차량이 몰렸다. 초기 비용을 감안해도 판매 확대 효과가 나타나고 있다.","주유소 할인 경쟁 심화","경쟁점의 할인으로 예상보다 고객 확보가 더디다. 가격 인하로 판매 마진도 줄었다."),
        new StockEvent(1,"저장시설 정기 점검 시작","연료 시설 점검…공급 영향 주목","회사가 저장시설 일부를 점검한다. 이상이 없다면 단기간에 재가동할 계획이다.","시설 점검 조기 종료","주요 설비에서 문제가 발견되지 않았다. 공급이 정상화되며 물류 비용도 줄어들었다.","추가 보수 필요…재가동 연기","노후 설비에 대한 보수가 필요해졌다. 우회 공급 비용이 늘고 있다."),
        new StockEvent(1,"도심 차량 통행량 변화","교통 수요와 연료 판매 전망 엇갈려","도시 행사를 앞두고 차량 이동이 늘어날 것으로 예상된다. 다만 일부 구간의 통행 제한이 판매량에 영향을 줄 수 있다.","행사 기간 연료 판매 증가","예상보다 많은 방문 차량이 유입됐다. 주요 지점 판매량이 증가했다.","통행 제한에 주유소 방문 감소","통제 구간 주변의 차량 이동이 줄었다. 행사 수요가 실제 판매 증가로 이어지지 못했다."),
        new StockEvent(2,"야간 배송 증가…인력 추가 모집","배달 수요 늘어도 비용 부담 남아","야간 배송량이 증가했다. 회사는 인력 충원을 추진하지만 인건비와 연료비 상승이 부담이다.","배송 경로 개선으로 비용 절감","증가한 물량을 효율적으로 묶어 배송했다. 건당 비용이 줄며 수익성이 개선됐다.","배송 지연 보상금 급증","인력 확보가 늦어 배송 지연이 늘었다. 보상금 부담으로 매출 증가 효과가 줄었다."),
        new StockEvent(2,"대형 상점 배송 계약 협상","정기 배송 물량 확보 추진","대형 상점과 정기 배송 계약을 논의 중이다. 물량은 안정적이지만 계약 단가가 수익성을 좌우할 전망이다.","적정 단가로 배송 계약 체결","양측이 배송 단가에 합의했다. 기존 노선을 활용할 수 있어 추가 비용도 제한적이다.","낮은 단가에 수익성 우려","계약은 성사됐지만 단가가 기대에 못 미쳤다. 물량 증가에 비해 이익 기여가 작을 것으로 보인다."),
        new StockEvent(2,"새 배송 시스템 시험 운영","물류 시스템 개편…효율 개선 기대","새 배차 시스템이 일부 지역에 적용됐다. 운행 거리 단축이 기대되지만 초기 안정성 검증이 필요하다.","배차 개편으로 운행 거리 감소","시험 지역에서 배송 효율이 개선됐다. 회사는 적용 지역을 확대할 계획이다.","배차 장애로 주문 누락","새 시스템에서 주문 처리 오류가 발생했다. 복구와 고객 보상 비용이 발생했다."),
        new StockEvent(2,"경쟁 배달업체 도심 진출","배송 시장 경쟁 격화 예고","새 경쟁사가 할인 배송을 시작한다. 기존 고객의 충성도와 서비스 품질이 시험대에 올랐다.","정시 배송으로 고객 유지","주요 거래처가 기존 계약을 유지했다. 가격 인하 없이 고객 이탈을 막았다는 평가다.","할인 경쟁으로 마진 축소","고객 유지를 위해 배송료를 낮췄다. 물량은 유지됐지만 수익성이 악화됐다."),
        new StockEvent(2,"배송 인력 확보 나서","기사 충원으로 지연 해소 추진","회사가 배송 인력을 늘린다. 처리 능력 확대와 인건비 증가가 동시에 예상된다.","충원 완료…밀린 주문 해소","배송 인력이 안정적으로 확보됐다. 지연 보상 비용이 줄어 추가 인건비를 상쇄했다.","채용 비용 늘고 지원자는 부족","예상보다 높은 채용 비용이 들었다. 인력 부족도 지속돼 비용 부담이 커졌다."),
        new StockEvent(3,"외식업체와 공급 계약 추진","식재료 납품 확대…원가 부담 변수","여러 외식업체와 장기 납품 계약을 논의한다. 우유 가격 상승 속에서 공급 조건이 주목된다.","납품 가격 조정 합의","원가 상승을 반영한 공급 가격에 합의했다. 납품량 확대와 함께 이익 개선이 기대된다.","공급 가격 동결에 원가 부담","물량은 늘었지만 납품 가격은 동결됐다. 원재료비 증가가 수익을 압박한다."),
        new StockEvent(3,"우유 가격 상승에 대응 검토","치즈 생산 원가 부담 커져","원유 공급 가격이 올랐다. 회사는 가격 조정과 생산 효율 개선을 검토하고 있다.","생산 효율 개선으로 비용 상쇄","공정 개선으로 원재료 손실이 줄었다. 공급 가격 조정도 일부 반영됐다.","가격 인상 난항…이익 감소 우려","거래처가 가격 인상에 반대했다. 회사가 원가 상승분을 부담하게 됐다."),
        new StockEvent(3,"새 피자용 치즈 출시","신제품 식당 시식 평가 시작","신제품 치즈가 일부 식당에 공급됐다. 맛과 보관성에 대한 평가가 본격 주문량을 좌우할 전망이다.","식당 재주문 증가","시식 거래처에서 재주문이 늘었다. 제품 평가가 실제 매출로 이어지고 있다.","신제품 주문 기대 이하","초기 관심과 달리 재주문이 적었다. 판촉 비용 회수까지 시간이 필요해졌다."),
        new StockEvent(3,"냉장시설 이상 점검","보관 설비 문제…재고 영향 조사","냉장시설 일부에서 온도 이상이 감지됐다. 회사는 재고 상태를 확인하고 대체 보관 공간을 확보하고 있다.","신속 복구로 재고 피해 제한","대체 보관과 설비 복구가 빠르게 진행됐다. 납품 일정은 유지됐다.","재고 폐기와 납품 중단","일부 식재료의 보관 기준이 충족되지 않았다. 재고 폐기와 납품 지연으로 손실이 발생했다."),
        new StockEvent(3,"정기 위생 검사 진행","식재료 품질 점검 결과 주목","생산시설이 정기 검사를 받고 있다. 회사는 관리 절차를 준수하고 있다고 밝혔다.","위생 검사 적합 판정","검사에서 주요 항목이 기준을 충족했다. 거래처의 추가 발주 문의도 이어졌다.","일부 제품 회수 결정","검사에서 관리 문제가 확인됐다. 제품 회수와 개선 조치가 진행된다."),
        new StockEvent(4,"신형 휴대기기 공개 임박","신제품 기대 높아진 네온테크","새 기기 공개를 앞두고 관심이 높아졌다. 기대가 이미 가격에 반영된 만큼 실제 성능과 판매 실적이 중요하다.","예상 웃도는 성능…초기 물량 소진","공개된 제품의 성능이 기대를 웃돌았다. 초기 판매도 호조를 보였다.","무난한 성능에도 기대에는 미달","제품은 출시됐지만 차별점이 부족하다는 평가가 나왔다. 높아졌던 기대가 조정되고 있다."),
        new StockEvent(4,"신제품 출시 일정 조정","출시 연기…품질 개선 여부 주목","회사가 제품 완성도를 위해 출시를 미뤘다. 짧은 점검으로 끝날지 추가 지연이 발생할지는 불확실하다.","품질 개선 후 정상 출시","점검이 마무리돼 제품이 출시됐다. 초기 사용 평가도 양호하다.","출시 재연기에 예약 취소","추가 문제가 발견돼 일정이 다시 밀렸다. 예약 취소와 개발 비용 증가가 부담이다."),
        new StockEvent(4,"대형 판매점 입점 추진","전자기기 판매 경로 확대","대형 판매점과 입점 협상을 진행한다. 고객 접점은 늘지만 초기 재고와 판촉 비용이 필요하다.","입점 후 판매량 증가","새 판매 경로에서 수요가 확인됐다. 재고 회전도 예상보다 빨랐다.","판매 부진에 할인 확대","판매점 재고가 쌓여 할인 판매를 시작했다. 매출보다 마진 감소가 우려된다."),
        new StockEvent(4,"경쟁사 신제품 공개","전자기기 경쟁 심화…차별점 시험대","경쟁사가 비슷한 가격대의 제품을 공개했다. 소비자들은 성능과 사용 편의성을 비교하고 있다.","차별화 기능에 고객 관심 유지","사용 편의성이 좋은 평가를 받았다. 경쟁 제품 출시에도 판매가 유지됐다.","가격 경쟁에서 밀려 판매 둔화","경쟁 제품이 가격 대비 성능에서 좋은 평가를 받았다. 기존 제품 주문이 줄었다."),
        new StockEvent(4,"일부 기기 사용 오류 신고","제품 안정성 점검 착수","일부 사용자에게서 사용 중 오류가 보고됐다. 소프트웨어 문제인지 하드웨어 결함인지 조사 중이다.","업데이트로 오류 해결","소프트웨어 수정으로 문제가 해결됐다. 대규모 교환 없이 정상 사용이 가능해졌다.","하드웨어 결함으로 교환 확대","문제가 하드웨어에서 확인됐다. 교환 비용과 신뢰 회복 부담이 커졌다.")
    };
}}
